/**
 * @file src/lib/rocketSnapshot.ts
 * Read-only snapshot for RocketPanel main content.
 */

import type { GameRuntime } from '../types/game.js';
import type { RocketSnapshot, RocketRealtimeSnapshot } from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import {
  rocketSnapshotWouldChange,
  rocketRealtimeWouldChange,
} from '../stores/rocketSnapshotDiff.js';
import {
  buildRocketSnapshot,
  buildRocketRealtimeSnapshot,
  EMPTY_ROCKET_SNAPSHOT,
  EMPTY_ROCKET_REALTIME,
} from './rocketSnapshotBuilder.js';

export { buildRocketSnapshot, buildRocketRealtimeSnapshot, EMPTY_ROCKET_SNAPSHOT };

let lastRocketSnapshot: RocketSnapshot | null = null;
let lastRocketRealtime: RocketRealtimeSnapshot | null = null;

/** @internal Vitest only */
export function resetRocketSnapshotDedupForTests(): void {
  lastRocketSnapshot = null;
  lastRocketRealtime = null;
}

export function notifyRocketChanged(game: GameRuntime): void {
  const rocket = buildRocketSnapshot(game);
  if (lastRocketSnapshot && !rocketSnapshotWouldChange(lastRocketSnapshot, rocket)) return;
  lastRocketSnapshot = rocket;
  publish({ type: Evt.ROCKET_CHANGED, rocket });
}

export function notifyRocketRealtimeTick(game: GameRuntime): void {
  if (typeof game.updateRocketStakingPushSession === 'function') {
    game.updateRocketStakingPushSession(Date.now());
  }
  const realtime = buildRocketRealtimeSnapshot(game);
  if (realtime.stakingNeedsFullRebuild) {
    notifyRocketChanged(game);
  }
  if (lastRocketRealtime && !rocketRealtimeWouldChange(lastRocketRealtime, realtime)) return;
  lastRocketRealtime = realtime;
  publish({ type: Evt.ROCKET_TICK, realtime });
}

/** After user actions (deposit, recover, loan…) — refresh snapshot and realtime together. */
export function notifyRocketPanelRefresh(game: GameRuntime): void {
  notifyRocketChanged(game);
  lastRocketRealtime = null;
  notifyRocketRealtimeTick(game);
}
