/**
 * @file src/stores/rocketSnapshotDiff.ts
 */

import type { RocketSnapshot, RocketRealtimeSnapshot } from '../bus/snapshots.js';

function stakingSig(s: RocketSnapshot['staking']): string {
  const session = s.session;
  const items = s.stakeableItems.map((i) => `${i.key}|${i.canStake}`).join(';');
  const steal = s.stealFeedback ? '1' : '0';
  return `${s.timerText}|${session?.timerText ?? ''}|${session?.accumulatedText ?? ''}|${items}|${steal}|${s.emptyMessage ?? ''}`;
}

export function rocketSnapshotWouldChange(prev: RocketSnapshot, next: RocketSnapshot): boolean {
  return (
    prev.kpi.rj !== next.kpi.rj
    || prev.kpi.trustLevel !== next.kpi.trustLevel
    || prev.kpi.trustXpRatio !== next.kpi.trustXpRatio
    || prev.kpi.loanCap !== next.kpi.loanCap
    || prev.bank.balance !== next.bank.balance
    || prev.bank.bankCap !== next.bank.bankCap
    || prev.bank.bankAtCap !== next.bank.bankAtCap
    || prev.bank.optionsOpen !== next.bank.optionsOpen
    || prev.bank.autoInjectCombatHalf !== next.bank.autoInjectCombatHalf
    || prev.bank.autoInjectInterests !== next.bank.autoInjectInterests
    || prev.bank.rateText !== next.bank.rateText
    || prev.bank.interestPerMin !== next.bank.interestPerMin
    || prev.bank.interestPerHour !== next.bank.interestPerHour
    || prev.bank.projection24h !== next.bank.projection24h
    || prev.loan.debtText !== next.loan.debtText
    || prev.loan.debtBarPct !== next.loan.debtBarPct
    || prev.loan.debtCapPct !== next.loan.debtCapPct
    || prev.loan.debtStress !== next.loan.debtStress
    || prev.loan.statusText !== next.loan.statusText
    || prev.loan.active !== next.loan.active
    || prev.loan.borrowDisabled !== next.loan.borrowDisabled
    || prev.casino.hasSpins !== next.casino.hasSpins
    || prev.casino.spinsCountText !== next.casino.spinsCountText
    || stakingSig(prev.staking) !== stakingSig(next.staking)
  );
}

export function rocketRealtimeWouldChange(
  prev: RocketRealtimeSnapshot,
  next: RocketRealtimeSnapshot,
): boolean {
  return (
    prev.rj !== next.rj
    || prev.bankBalance !== next.bankBalance
    || prev.interestPerMin !== next.interestPerMin
    || prev.interestPerHour !== next.interestPerHour
    || prev.projection24h !== next.projection24h
    || prev.loanDebtText !== next.loanDebtText
    || prev.loanDebtBarPct !== next.loanDebtBarPct
    || prev.loanDebtCapPct !== next.loanDebtCapPct
    || prev.loanDebtStress !== next.loanDebtStress
    || prev.loanStatusText !== next.loanStatusText
    || prev.loanActive !== next.loanActive
    || prev.loanBorrowDisabled !== next.loanBorrowDisabled
    || prev.stakingTimerText !== next.stakingTimerText
    || !!prev.session !== !!next.session
    || prev.session?.timerText !== next.session?.timerText
    || prev.session?.accumulatedText !== next.session?.accumulatedText
    || prev.session?.gpsText !== next.session?.gpsText
    || prev.session?.riskText !== next.session?.riskText
    || prev.session?.progressPct !== next.session?.progressPct
    || prev.session?.nextTierHint !== next.session?.nextTierHint
    || prev.session?.isHighRisk !== next.session?.isHighRisk
  );
}
